const buf = await this.helpers.getBinaryDataBuffer(0, 'data');
const b64 = buf.toString('base64');
const mime = ($input.first().binary && $input.first().binary.data && $input.first().binary.data.mimeType) || 'image/jpeg';
const body = {
  model: 'openai-gpt-6-luna',
  messages: [{
    role: 'user',
    content: [
      { type: 'text', text: 'This image was sent to me on Telegram, possibly alongside a caption. Describe what it shows and transcribe every piece of readable text exactly as shown, in plain text. Be precise, no speculation.' },
      { type: 'image_url', image_url: { url: 'data:' + mime + ';base64,' + b64 } }
    ]
  }],
  temperature: 0.1,
  venice_parameters: { disable_thinking: true }
};
return [{ json: { body } }];

// Get Last Exchange returns this chat's last log rows, newest first (one row per bot message).
const rows = $input.all().map((i) => i.json || {}).filter((r) => r.createdAt);
const row = rows[0] || {};
const src = $('Build Input From Text').isExecuted ? 'Build Input From Text' : ($('Build Input From Voice').isExecuted ? 'Build Input From Voice' : 'Build Input From Image');
const cur = $(src).first().json;
const chatInput = String(cur.chatInput ?? '');
const replyTo = ($('Receive Telegram Message').first().json.message || {}).reply_to_message || null;
const classifierRan = $('Router: Classify Request').isExecuted;
const base = { chat_id: String(cur.chat_id), chatInput: chatInput };
const send = (request, agent, extra) => [{ json: { ...base, request_text: request, follow_agent: agent, redirected: false, explicit_tag: false, ...extra } }];
const hoursAgo = (r) => DateTime.now().diff(DateTime.fromISO(r.createdAt), 'hours').hours;
const AGENTS = ['productivity', 'budget', 'subscriptions', 'project'];

// A reply can end with a tag line. "➡️ #budget" alone redirects the user's request; "➡️ #productivity <request>" carries the request for the next agent (the Projects Coach hands weekly goals over this way).
const tagLine = (text) => String(text || '').match(/(?:^|\n)[ \t*_]*(?:➡️?)?[ \t]*#(productivity|budget|subscriptions|project)\b[ \t:*_]*([^\n]*)\s*$/i); // only the reply's last line
const handoffIn = (text, agent) => {
  const m = tagLine(text);
  if (!m || (agent && m[1].toLowerCase() !== agent)) return '';
  const t = m[2].replace(/[*_]+$/, '').trim();
  return t.length > 15 ? t : '';
};
// What a tag line passes on: the handed-over request (or his earlier message), plus what he writes now (user, 2026-10-26)
const passOn = (handed, earlier, now, replied) => {
  const before = handed || earlier;
  if (isFiller(now)) return before || now;
  return before ? before + '\n\nHe adds: ' + now : now + quote(replied);
};
const quote = (text) => '\n\n(He is replying to this earlier message: "' + String(text || '').replace(/\s+/g, ' ').trim().slice(0, 300) + '")';

// Sam's chat (0000000000) is a fixed rule, not a model decision: every message, tag or reply goes to the Family Budget Coach only.
if (String(cur.chat_id) === '0000000000') return send(chatInput + (replyTo && replyTo.text ? quote(replyTo.text).replace('He is replying', 'She is replying') : ''), 'budget');

// Words that add nothing: "yes", "try again", "please", "do it".
const isFiller = (text) => String(text).replace(/\b(please|ok|okay|yes|yeah|sure|try|again|retry|redo|resend|do|it|send|there|now|thanks)\b/ig, '').replace(/[^\p{L}\p{N}]+/gu, '') === '';
const explicit = chatInput.match(/(?:#|\bhashtag\s+)(productivity|budget|subscriptions|project|idea)\b/i);
const rest = chatInput.replace(/(?:#|\bhashtag\s+)(productivity|budget|subscriptions|project|idea)\b/ig, ' ').replace(/\s+/g, ' ').trim();
const bare = isFiller(rest);

// 0. A Telegram reply points at one message: that message decides, with no time limit.
// Checked once, before the classifier; a reply that cannot be traced goes to the classifier like a new message.
if (replyTo && !classifierRan) {
  const fromBot = !!(replyTo.from && replyTo.from.is_bot);
  const rid = Number(replyTo.message_id);
  const r = rows.find((x) => Number(fromBot ? x.reply_message_id : x.user_message_id) === rid) || null;
  const original = r ? String(r.user_message || '') : (fromBot ? '' : String(replyTo.text || ''));
  const replied = r ? String(r.agent_reply || '') : (fromBot ? String(replyTo.text || '') : '');
  if (explicit) {
    const agent = explicit[1].toLowerCase() === 'idea' ? 'project' : explicit[1].toLowerCase();
    if (!fromBot && original) return send(original + (bare ? '' : '\n\nNote: ' + rest), agent, { explicit_tag: true });
    if (fromBot && bare && (handoffIn(replied, agent) || original)) return send(handoffIn(replied, agent) || original, agent, { explicit_tag: true });
    if (fromBot && !bare) return send((explicit[1].toLowerCase() === 'idea' ? 'Idea: ' : '') + rest + quote(replied), agent, { explicit_tag: true });
  } else if (fromBot) {
    const m = tagLine(replied);
    // A reply to a message that ends with a tag line goes to the tagged agent, whatever he writes (user, 2026-10-26)
    if (m) return send(passOn(handoffIn(replied, m[1].toLowerCase()), original, chatInput, replied), m[1].toLowerCase(), { redirected: true });
    if (r && AGENTS.includes(String(r.agent))) return send(chatInput + quote(replied), String(r.agent));
    if (r && original) return send(original + '\n\n' + chatInput, 'classify'); // answer to the Router's clarifying question
    return send(chatInput, 'classify');
  } else if (r && AGENTS.includes(String(r.agent))) {
    return send(chatInput + quote(original), String(r.agent));
  } else {
    return send(chatInput, 'classify');
  }
}

const lastAgent = String(row.agent ?? '');
const lastUser = String(row.user_message ?? '');
const lastReply = String(row.agent_reply ?? '');
// Follow the last agent for 6 hours; a last reply that hands a request over stays valid for 48 hours.
const recent = !!(row.createdAt && lastAgent && (hoursAgo(row) < 6 || (hoursAgo(row) < 48 && handoffIn(lastReply))));

// 1. The user wrote an explicit tag (#budget, #productivity, #subscriptions, #project, #idea): that agent, always. #idea goes to the project agent with the prefix "Idea: ".
if (explicit) {
  const agent = explicit[1].toLowerCase();
  const isIdea = agent === 'idea';
  // "#productivity yes" also finds the newest request handed to that agent in the last 48 hours, even if other agents answered since.
  const saysYes = /\b(yes|yeah|ok|okay|sure)\b/i.test(rest);
  const lastTagged = recent && !!tagLine(lastReply) && tagLine(lastReply)[1].toLowerCase() === agent;
  const handed = bare && saysYes && !lastTagged ? rows.filter((x) => hoursAgo(x) < 48).map((x) => handoffIn(x.agent_reply, agent)).find((t) => t) || '' : '';
  // a bare tag, or a tag plus only filler ("try again", "please", "do it"), means: send the last request there
  const request = bare ? (handed || (recent ? (handoffIn(lastReply, agent) || lastUser) : '')) : (isIdea ? 'Idea: ' + rest : rest);
  return [{ json: { ...base, request_text: request, follow_agent: request ? (isIdea ? 'project' : agent) : '', redirected: false, explicit_tag: true } }];
}

// 2. Follow the conversation. The Router's own "I couldn't tell what you mean" reply is not one: follow the agent that spoke before it.
const conv = lastAgent === 'router' ? (rows.find((x) => AGENTS.includes(String(x.agent))) || {}) : row;
const convAgent = String(conv.agent ?? '');
const convUser = String(conv.user_message ?? '');
const convReply = String(conv.agent_reply ?? '');
const convRecent = !!(conv.createdAt && convAgent && (hoursAgo(conv) < 6 || (hoursAgo(conv) < 48 && handoffIn(convReply))));
// The last reply ended with a tag line (➡️ #project): the next message goes to that agent for 6 hours, with what he writes now;
// a bare "yes" or "try again" also within 48 hours when that line hands a request over (user, 2026-10-26).
// "Follows A Tag Line?" sends such a message here before the classifier, with the same test.
const tag = tagLine(convReply);
const handedConv = tag ? handoffIn(convReply, tag[1].toLowerCase()) : '';
const tagRecent = !!(tag && conv.createdAt && (hoursAgo(conv) < 6 || (hoursAgo(conv) < 48 && handedConv && isFiller(chatInput))));
if (tagRecent) return send(passOn(handedConv, convUser, chatInput, convReply), tag[1].toLowerCase(), { redirected: true });
const followAgent = convRecent ? convAgent : '';
return [{ json: { ...base, request_text: chatInput, follow_agent: followAgent, redirected: false, explicit_tag: false } }];
